    X=[]
    def add(a,b,action,reason,sources,fids): X.append({'pair':[a,b],'action':action,'reason':reason,'source_entity_ids':sources,'fact_ids':fids})
    add('base_frame','yaw_pin','exclude','measured interference press fit rigidly fixes the yaw pin in the base',['port/base_frame/yaw_axis','port/yaw_pin/yaw_shaft'],['fit/base_frame/yaw_axis/yaw_pin/yaw_shaft','pair/base_frame/yaw_pin'])
    add('yaw_carriage','yaw_pin','exclude','measured clearance running fit is represented by yaw hinge',['port/yaw_carriage/yaw_bore','port/yaw_pin/yaw_shaft','motion_joint/base_yaw_revolute'],['fit/yaw_pin/yaw_shaft/yaw_carriage/yaw_bore','pair/yaw_carriage/yaw_pin','nearby/yaw_carriage/yaw_pin'])
