    add('wrist_link','end_effector_pointer','exclude','coincident mounting faces rigidly carry pointer with wrist',['port/wrist_link/tool_mount','port/end_effector_pointer/mount_face'],['fit/wrist_link/tool_mount/end_effector_pointer/mount_face','pair/end_effector_pointer/wrist_link','nearby/end_effector_pointer/wrist_link'])
